-- Table: inventory_stock_adjustment_detail
-- Source: accounting_admin_db.sql (5. Inventory)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS inventory_stock_adjustment_detail (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    adjustment_id        BIGINT NOT NULL REFERENCES inventory_stock_adjustment(id) ON DELETE CASCADE,
    line_number          INTEGER NOT NULL CHECK (line_number > 0),
    product_id           BIGINT NOT NULL REFERENCES masterdata_product(id),
    uom_id               BIGINT NOT NULL REFERENCES masterdata_uom(id),
    system_quantity      NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK (system_quantity >= 0),
    actual_quantity      NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK (actual_quantity >= 0),
    difference_quantity  NUMERIC(18,4) NOT NULL DEFAULT 0,
    unit_cost            NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
    total_cost           NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (total_cost >= 0),
    UNIQUE (adjustment_id, line_number)
);
